                        return -10;
#else
                        goto continue2; /* silent fail return -10; invalid ip format ,probably like 1000.3.12341.2 */
#endif
                }
                buffer[0] = '\0';
                strncat((char *)buffer, pos, oldlen);
                buffer[oldlen] = '\0';
                i = parse_ip_address(buffer, &locatedIp);
                if(i == 0) {
